function drawSquirtleWaterTurtle(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 2.8;

  const tailLag = breathPhase - 0.45;
  const tailSwayX = Math.sin(tailLag) * 5.0;
  const tailSwayY = Math.cos(tailLag) * 3.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Mai rùa
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(8, by + 10, 16, 20, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#92400e';
  ctx.beginPath(); ctx.ellipse(10, by + 10, 14, 18, 0, 0, Math.PI * 2); ctx.fill();

  // Đuôi xoáy nước
  const tx = 22 + tailSwayX;
  const ty = by + 14 + tailSwayY;
  ctx.fillStyle = '#38bdf8';
  ctx.beginPath(); ctx.arc(tx, ty, 10, 0, Math.PI * 2); ctx.fill();

  // Thân lam & yếm bụng
  ctx.fillStyle = '#38bdf8';
  ctx.beginPath(); ctx.ellipse(-4, by + 14, 16 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.ellipse(-8, by + 14, 10 * sX, 12 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#38bdf8';
  ctx.beginPath(); ctx.roundRect(-18, by + 26, 9, 10, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-2,  by + 26, 9, 10, 4); ctx.fill();

  // Đầu
  ctx.beginPath(); ctx.ellipse(-6, by - 10, 20 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Mắt đỏ
  if (!blink) {
    ctx.fillStyle = '#b91c1c';
    ctx.beginPath(); ctx.ellipse(-12, by - 10, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(2,   by - 10, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-13, by - 13, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(1,   by - 13, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Mỏ
  ctx.strokeStyle = '#0284c7';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-14, by - 2); ctx.lineTo(-4, by); ctx.lineTo(4, by - 2);
  ctx.stroke();

  // Tay nhỏ
  ctx.fillStyle = '#38bdf8';
  ctx.beginPath(); ctx.arc(-18, by + 8, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(4,   by + 8, 4, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
